// AWI: perbaikan sekali jalan (form WPForms + layar sambutan). Hapus setelah dipakai.
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/fix', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$bs = chr(92);
			$url_esc = 'https:' . $bs . '/' . $bs . '/bydjkt.co.id' . $bs . '/wp-content' . $bs . '/uploads' . $bs . '/wpforms' . $bs . '/themes' . $bs . '/stock-photos' . $bs . '/max-fuchs-Nm6ojlDO-5c-unsplash.jpg';
			$url_raw = 'https://bydjkt.co.id/wp-content/uploads/wpforms/themes/stock-photos/max-fuchs-Nm6ojlDO-5c-unsplash.jpg';
			$q1 = '"';
			$q2 = $bs . '"';
			$out = array();
			foreach (array(9586, 9588) as $id) {
				$c = $wpdb->get_var($wpdb->prepare("SELECT post_content FROM {$wpdb->posts} WHERE ID = %d", $id));
				if (!$c) { $out[$id] = 'not found'; continue; }
				$n = $c;
				$n = str_replace(array($url_esc, $url_raw), 'url()', $n);
				foreach (array($q1, $q2) as $q) {
					$n = str_replace('backgroundImage' . $q . ':' . $q . 'stock' . $q, 'backgroundImage' . $q . ':' . $q . 'none' . $q, $n);
				}
				$n = str_replace(' (Bunga 0%)', '', $n);
				$n = str_replace('12 bulan ' . $bs . '/ 1 Tahun', '12 Bulan ' . $bs . '/ 1 Tahun', $n);
				$out[$id] = array('changed' => $n !== $c, 'left_bydjkt' => substr_count($n, 'bydjkt'), 'left_bunga' => substr_count($n, 'Bunga 0'), 'json_ok' => null !== json_decode($n));
				if ($n !== $c && null !== json_decode($n)) {
					$wpdb->update($wpdb->posts, array('post_content' => $n), array('ID' => $id));
					clean_post_cache($id);
				}
			}
			$up = wp_upload_dir();
			$f = $up['basedir'] . '/wpforms/themes/themes-custom.json';
			if (is_file($f)) {
				$c = file_get_contents($f);
				$n = str_replace(array($url_esc, $url_raw), 'url()', $c);
				foreach (array($q1, $q2) as $q) {
					$n = str_replace('backgroundImage' . $q . ':' . $q . 'stock' . $q, 'backgroundImage' . $q . ':' . $q . 'none' . $q, $n);
				}
				if ($n !== $c && null !== json_decode($n)) { file_put_contents($f, $n); }
				$out['themes'] = array('changed' => $n !== $c, 'left' => substr_count($n, 'bydjkt'));
			}
			// Layar sambutan: lewati untuk pengunjung dari iklan & mesin pencari.
			$old = <<<'X'
(function(){try{if(sessionStorage.getItem('awiWel'))return;
X;
			$new = <<<'X'
(function(){var awq=location.search,awr=document.referrer||'';if(/[?&](gclid|gbraid|wbraid|gad_source|gad_campaignid|utm_source|utm_medium|fbclid|ttclid)=/i.test(awq)||/google[.]|bing[.]|yahoo[.]|duckduckgo|ecosia|yandex/i.test(awr))return;try{if(sessionStorage.getItem('awiWel'))return;
X;
			$t = $wpdb->prefix . 'snippets';
			$code = $wpdb->get_var($wpdb->prepare("SELECT code FROM $t WHERE id = %d", 25));
			if ($code && false === strpos($code, 'awq=location.search') && false !== strpos($code, $old)) {
				$code2 = str_replace($old, $new, $code);
				if (function_exists('Code_Snippets' . $bs . 'get_snippet')) {
					$s = call_user_func('Code_Snippets' . $bs . 'get_snippet', 25);
					$s->code = $code2;
					call_user_func('Code_Snippets' . $bs . 'save_snippet', $s);
					$out['s25'] = 'saved via API';
				} else {
					$wpdb->update($t, array('code' => $code2), array('id' => 25));
					$out['s25'] = 'saved via db';
				}
			} else {
				$out['s25'] = $code ? (false !== strpos($code, 'awq=') ? 'already' : 'pattern not found') : 'no code';
			}
			$chk = $wpdb->get_var($wpdb->prepare("SELECT code FROM $t WHERE id = %d", 25));
			$out['s25_has_skip'] = false !== strpos($chk, 'awq=location.search');
			return $out;
		},
	));
});

