add_action('template_redirect', function () {
	if (is_admin() || wp_doing_ajax() || is_feed() || (defined('REST_REQUEST') && REST_REQUEST)) return;
	ob_start(function ($html) {
		if (!is_string($html) || false === stripos($html, '<body')) return $html;
		$parts = preg_split('#(<body\b)#i', $html, 2, PREG_SPLIT_DELIM_CAPTURE);
		if (count($parts) < 3) return $html;
		$body = preg_replace_callback('#<img\b[^>]*>#i', function ($m) {
			$t = $m[0];
			if (preg_match('#\bloading=|data-no-lazy|data-src=|fetchpriority=|skip-lazy|custom-logo#i', $t)) return $t;
			return preg_replace('#^<img\b#i', '<img loading="lazy" decoding="async"', $t);
		}, $parts[2]);
		return $parts[0] . $parts[1] . $body;
	});
}, 97);
